<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Pterodactyl\Models\Nest; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\StartupPresets; class StartupController extends Controller { public function __construct(private readonly AlertsMessageBag $alert) { } public function index(): View { return view('admin.dezerx.startup.index', [ 'presets' => StartupPresets::all(), 'nests' => Nest::query()->with('eggs')->orderBy('name')->get(), ]); } public function store(Request $request): RedirectResponse { if (StartupPresets::store($this->data($request))) { $this->alert->success('That startup command has been added.')->flash(); } else { $this->alert->danger('That startup command was not added: the panel holds ' . StartupPresets::MAX . ' of them, which is as many as it keeps.')->flash(); } return redirect()->route('admin.dezerx.startup'); } public function seed(): RedirectResponse { $counts = StartupPresets::seed(); if ($counts['added'] === 0) { $this->alert->info( $counts['duplicate'] > 0 ? 'Nothing was added: the ready made commands are already on this page.' : 'Nothing was added: no egg on this panel takes any of the ready made commands.' )->flash(); return redirect()->route('admin.dezerx.startup'); } $message = $counts['added'] . ' ' . ($counts['added'] === 1 ? 'command was' : 'commands were') . ' added, switched off. Read them, pick the eggs, then turn on the ones you want.'; if ($counts['duplicate'] > 0) { $message .= ' ' . $counts['duplicate'] . ' were already here and were left alone.'; } if ($counts['unsuited'] > 0) { $message .= ' ' . $counts['unsuited'] . ' were skipped: no egg on this panel takes them.'; } if ($counts['refused'] > 0) { $message .= ' ' . $counts['refused'] . ' did not fit: this page holds ' . StartupPresets::MAX . '.'; } $this->alert->success($message)->flash(); return redirect()->route('admin.dezerx.startup'); } public function update(Request $request, string $preset): RedirectResponse { StartupPresets::update($preset, $this->data($request)); $this->alert->success('That startup command has been saved.')->flash(); return redirect()->route('admin.dezerx.startup'); } public function destroy(string $preset): RedirectResponse { StartupPresets::delete($preset); $this->alert->success('That startup command has been removed.')->flash(); return redirect()->route('admin.dezerx.startup'); } private function data(Request $request): array { $validated = $request->validate([ 'label' => ['required', 'string', 'max:60'], 'description' => ['nullable', 'string', 'max:200'], 'command' => ['required', 'string', 'max:2000'], 'eggs' => ['sometimes', 'array'], 'eggs.*' => ['string'], 'enabled' => ['sometimes', 'boolean'], ]); return [ 'label' => $validated['label'], 'description' => $validated['description'] ?? '', 'command' => $validated['command'], 'eggs' => $validated['eggs'] ?? [], 'enabled' => (bool) ($validated['enabled'] ?? false), ]; } } 